import { Swirl, type SwirlProps } from "@paper-design/shaders-react";
import { forwardRef, useCallback, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const NEUTRAL_COLORS = ["#52527a", "#3a3a5c", "#232338"];

interface ShaderSwirlProps extends Omit<SwirlProps, "frame" | "ref"> {}

function ShaderSwirlBase({
  speed = 1,
  colors = NEUTRAL_COLORS,
  colorBack = "#12121a",
  bandCount = 4,
  twist = 0.1,
  softness = 0.2,
  className,
  ...rest
}: ShaderSwirlProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const [handle] = useState(() => delayRender("shader-swirl"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      <Swirl
        speed={0}
        frame={(frame / fps) * speed * 1000}
        colors={colors}
        colorBack={colorBack}
        bandCount={bandCount}
        twist={twist}
        softness={softness}
        fit="cover"
        width={width}
        height={height}
        {...rest}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  bandCount: {
    type: "number",
    min: 1,
    max: 12,
    step: 1,
    default: 4,
    description: "Bands",
    hiddenFromList: false,
  },
  twist: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.1,
    description: "Twist",
    hiddenFromList: false,
  },
  softness: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.2,
    description: "Softness",
    hiddenFromList: false,
  },
  colorBack: {
    type: "color",
    default: "#12121a",
    description: "Background",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["speed","bandCount","twist","softness","colorBack"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  speed: 1,
  bandCount: 4,
  twist: 0.1,
  softness: 0.2,
  colorBack: "#12121a",
};

type ShaderSwirlElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShaderSwirlBase>;

const ShaderSwirlInner = forwardRef<
  HTMLDivElement,
  ShaderSwirlElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShaderSwirl>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShaderSwirlBase
          {...(componentProps as unknown as ComponentProps<typeof ShaderSwirlBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShaderSwirl = Interactive.withSchema({
  Component: ShaderSwirlInner,
  componentName: "<ShaderSwirl>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
